from .collector import HeatConfigCollector, HeatFilesCollector
from .mapper import CbtsMapper
from .model import CbtsModel
from taf.gnb.deployment.heat_templates.files import TemplateSerializer
import os


class Provider(object):
    def __init__(self, bts_yaml='config_bts.yaml', net_yaml='config_ext_net.yaml',
                 flavors_yaml='config_flavor.yaml', bts_env='config_bts.env',
                 net_env='config_ext_net.env'):

        self.reader = TemplateSerializer()
        self.bts_dir = bts_env
        self.bts_yaml = bts_yaml
        self.net_yaml = net_yaml
        self.flavors_yaml = flavors_yaml
        files_collector = HeatFilesCollector(self.reader)
        self.config_collector = HeatConfigCollector(reader=files_collector,
                                                    bts_env_filename=bts_env,
                                                    net_env_filename=net_env)

    def read_from_files(self, cfg_dirpath):
        heat_stacks = self.config_collector.from_files(cfg_dirpath)
        mapper = CbtsMapper(heat_stacks)
        is_remote_file = self.bts_dir.startswith("http://") or self.bts_dir.startswith("https://")
        if is_remote_file:
            path_to_config_file = self.bts_dir
        else:
            path_to_config_file = os.path.join(cfg_dirpath, self.bts_dir)
        serializer_load = self.reader.load(path_to_config_file)
        try:
            resource_registry = serializer_load.get_value_from_template('resource_registry')
        except KeyError:
            resource_registry = None
        return CbtsModel(heat_stacks=heat_stacks,
                         mapper=mapper,
                         cfg_dir=cfg_dirpath,
                         resource_registry=resource_registry,
                         bts_yaml=self.bts_yaml,
                         net_yaml=self.net_yaml,
                         flavors_yaml=self.flavors_yaml)
